  Let SPhi : bv_unsigned sp0 <= 0x800000000000 := proj1 (proj2 Hvsp).
  Let SPal : bv_unsigned sp0 mod 16 = 0 := proj2 (proj2 Hvsp).
  Notation P := (Z.of_nat (length path)).
