  Lemma buf_fact_block : forall vals M log (a : Z) n v,
    vals_ev vals 0 = sp0 -> log_out_b 0 (BUF_LO + NPRE) BUF_HI IHI log = true ->
    bv_unsigned sp0 + (BUF_LO + NPRE) <= a -> a + Z.of_nat n <= bv_unsigned sp0 + BUF_HI ->
