  Definition srA0 : list expr :=
    map (fun i => match i with 0 => ELit 0 | 2 => spx (-128) | 4 => ELit 0x6617f0 | 18 => EVar 2 | _ => EVar (3 + i) end)%nat (seq 0 32).
  Definition knA0 : list kentry := [KImg 0x10000 0x4e000; KImg 0x119000 0x121000].
  Definition rA := Eval vm_compute in sym_exec RSEGS 100 true [0x612dc] scr0 (SS 0xa41c8 srA0 [] knA0 35) [].
  Lemma rA_facts : s_pc (fst (fst rA)) = 0x612dc /\ snd (fst rA) = [] /\ s_log (fst (fst rA)) = [].
  Proof. vm_compute. repeat split; reflexivity. Qed.

  (* [comment removed for export] *)
  Definition ot_vals0 (R1 : bvmap 5 word) : list word := [sp0; Z_to_bv 64 can; pp] ++ junk_vals R1.
  Definition ot_vals (R1 R2 : bvmap 5 word) : list word := ot_vals0 R1 ++ junk_vals R2.

  Lemma ot_vals0_len : forall R1, length (ot_vals0 R1) = 35%nat.
  Proof. intros. unfold ot_vals0. rewrite length_app, junk_vals_length. reflexivity. Qed.
